  if ('offset' in args) {
    if (!isInteger(args.offset) || args.offset < 0) {
      throw new Error('offset must be a non-negative integer');
    }
    offset = args.offset;
  }
  // limit
  let limit = 2;
  if ('limit' in args) {
    if (!isInteger(args.limit) || args.limit < 1 || args.limit > 5) {
      throw new Error('limit must be an integer between 1 and 5');
